from jsonb_to_recordset($json$[{"id":"che-so-276","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A solute that should give $\\Delta T_b = 0.20$ K actually gives 0.30 K. The van’t Hoff factor is","options":["1.5","0.67","2.0","0.20"],"answer_index":0,"explanation":"i = 0.30 / 0.20 = 1.5.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-277","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Observed molar mass of NaCl in water is 30 g mol⁻¹ (formula mass 58.5). The factor i is nearest","options":["1.95","0.51","3.00","1.00"],"answer_index":0,"explanation":"i = 58.5 / 30 = 1.95, close to complete dissociation into two ions.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-278","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For dimerisation with $\\alpha = 0.40$, i equals","options":["0.80","1.40","0.40","2.00"],"answer_index":0,"explanation":"i = 1 − $\\alpha$(1 − 1/n) = 1 − 0.40/2 = 0.80.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-279","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 0.10 m aqueous Ca(NO3)2 solution is 70% dissociated. Using $K_f = 1.86$ K kg mol⁻¹, the freezing-point depression is nearest","options":["0.45 K","0.19 K","0.56 K","1.86 K"],"answer_index":0,"explanation":"n = 3, i = 1 + 2 × 0.70 = 2.40; $\\Delta T_f = 2.40 \\times 1.86 \\times 0.10 = 0.446$ K ≈ 0.45 K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-280","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 0.050 M weak electrolyte is 40% dissociated into two ions. At 300 K (R = 0.0821 L atm K⁻¹ mol⁻¹), osmotic pressure is nearest","options":["1.72 atm","1.23 atm","0.050 atm","2.46 atm"],"answer_index":0,"explanation":"i = 1.40; $\\pi = iCRT = 1.40 \\times 0.050 \\times 0.0821 \\times 300 \\approx 1.72$ atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"vanthoff-abnormal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-281","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two liquids that dissolve in each other in all proportions are called","options":["completely miscible","immiscible","partially miscible","always azeotropic"],"answer_index":0,"explanation":"Complete miscibility means a single liquid phase at every composition.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"miscibility-azeotrope","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-282","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Phenol and water below the consolute temperature form","options":["two liquid layers (partially miscible)","a single ideal gas","a solid alloy","an azeotrope only"],"answer_index":0,"explanation":"They are the usual Intermediate example of a pair with a limited mutual solubility.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"miscibility-azeotrope","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-283","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An azeotrope is a constant-boiling mixture whose vapour has","options":["the same composition as the boiling liquid","a composition richer in the less volatile component always","zero pressure","only water"],"answer_index":0,"explanation":"Liquid and vapour compositions coincide, so simple distillation does not change the composition.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"miscibility-azeotrope","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-284","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Minimum-boiling azeotropes arise from","options":["positive deviations from Raoult’s law","negative deviations from Raoult’s law","strictly ideal behaviour","Henry’s law for a solid"],"answer_index":0,"explanation":"A maximum in the p–x curve corresponds to a minimum in the boiling-point curve.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"miscibility-azeotrope","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-285","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Maximum-boiling azeotropes arise from","options":["negative deviations from Raoult’s law","positive deviations from Raoult’s law","$\\Delta H_{\\mathrm{mix}} = 0$","a large $K_H$"],"answer_index":0,"explanation":"A minimum in p versus x is a maximum on the T–x boiling diagram.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"miscibility-azeotrope","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
